import type { Asset, Project } from "./model";

export type RuleMarkKind = "smoking" | "drinking";
const defaults: Record<RuleMarkKind, Asset> = {
  smoking: {
    id: "builtin-rule-smoking",
    name: "禁煙の標準マーク",
    mime: "image/png",
    width: 960,
    height: 960,
    data: "data:image/png;base64,",
  },
  drinking: {
    id: "builtin-rule-drinking",
    name: "禁酒の標準マーク",
    mime: "image/png",
    width: 1280,
    height: 1280,
    data: "data:image/png;base64,",
  },
};
export function defaultRuleMark(kind: RuleMarkKind): Asset {
  return defaults[kind];
}
export function resolveAsset(p: Project, id: string): Asset | undefined {
  return p.assets[id] ?? Object.values(defaults).find((a) => a.id === id);
}
